import { showModal } from '@ui-kit/Modal';

import ObstacleSelectModal from './ObstacleSelectModal';
import { ISearchObstacleCriteria } from '../../@services/obstacles.service';
import { IObstacle } from '../../@types/obstacles.types';

export const searchAndSelectObstacleInModalAsync = async (
  criteria?: ISearchObstacleCriteria,
): Promise<IObstacle> => {
  return new Promise((resolve) => {
    showModal({
      title: 'Найти POI',
      children: (clos: () => void) => (
        <ObstacleSelectModal
          criteria={criteria}
          onChange={(res) => {
            resolve(res);
            clos();
          }}
        />
      ),
    });
  });
};
